package fr.hydrosea.abonnements.application;
import fr.hydrosea.abonnements.application.ModelesAbonnements.CommandeAjouterParticipant;import fr.hydrosea.abonnements.application.ModelesAbonnements.CommandeCreerContrat;import fr.hydrosea.abonnements.application.ModelesAbonnements.CommandeModifierContrat;import fr.hydrosea.abonnements.application.ModelesAbonnements.VueContrat;import fr.hydrosea.abonnements.application.ModelesAbonnements.VueParticipant;import fr.hydrosea.evenements.application.PortEvenements;import java.util.List;import java.util.Map;import java.util.UUID;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ServiceAbonnements {private final PortAbonnements port;private final PortEvenements evenements;public ServiceAbonnements(PortAbonnements port,PortEvenements evenements){this.port=port;this.evenements=evenements;}public List<VueContrat> lister(){return port.lister();}public VueContrat consulter(UUID id){return port.obtenir(id);}
 @Transactional public VueContrat creer(CommandeCreerContrat c,UUID correlation){UUID id=UUID.randomUUID();var v=port.creer(id,port.prochaineReference(),c,correlation);publier("CONTRAT_CREE",id,correlation);return v;}@Transactional public VueContrat modifier(UUID id,int version,CommandeModifierContrat c,UUID correlation){var v=port.modifier(id,version,c);publier("CONTRAT_MODIFIE",id,correlation);return v;}@Transactional public VueParticipant ajouterParticipant(UUID id,CommandeAjouterParticipant c,UUID correlation){var v=port.ajouterParticipant(id,c);publier("PARTICIPANT_AJOUTE",id,correlation);return v;}@Transactional public VueContrat valider(UUID id,int version,UUID correlation){var v=port.valider(id,version,correlation);publier("CONTRAT_A_VALIDER",id,correlation);publier("CONTRAT_VALIDE",id,correlation);return v;}@Transactional public VueContrat activer(UUID id,int version,UUID correlation){var v=port.activer(id,version,correlation);publier("CONTRAT_ACTIVE",id,correlation);return v;}private void publier(String type,UUID id,UUID correlation){evenements.enregistrer(type,"CONTRAT",id,correlation,Map.of("identifiant",id));}}
